add_filter( 'woocommerce_logout_default_redirect_url', 'perfectpixel_logout_redirect' );

function perfectpixel_logout_redirect( $url ) {
	$target = trim( '{{logout_redirect_url}}' );
	if ( '' === $target ) {
		return $url;
	}
	return wp_validate_redirect( 0 === strpos( $target, '/' ) ? home_url( $target ) : $target, $url );
}
